from pathlib import Path
import re

root = Path(__file__).resolve().parents[1]
source = (root / 'src/retailflow/templates/dashboard/home.html').read_text(encoding='utf-8')
shell = source.split('<section class="content">')[0]
shell = re.sub(r'{%.*?%}', '', shell, flags=re.S)
shell = re.sub(r'{{ company.company_name }}', 'Your company', shell)
shell = re.sub(r'{{ user.first_name.*?}}', 'A', shell)
shell = re.sub(r'{{ user.get_full_name.*?}}', 'Administrator', shell)
shell = shell.replace('href=""', 'href="#"')
shell = shell.replace('Search anything...', 'Search navigation...')
css = '''
.content{max-width:1600px;margin:auto}.preview-note{background:var(--cream);padding:10px 20px;text-align:center;font-size:11px;border-bottom:1px solid var(--line)}
.page-header{justify-content:space-between;margin-bottom:26px}.page-header h1{font-size:30px;text-transform:none;line-height:1.2}.page-header p{line-height:1.6}.kicker{margin-bottom:8px}
.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.button{background:var(--ink);color:var(--bg);border:1px solid var(--ink);padding:11px 15px;border-radius:8px;text-decoration:none;font-size:12px;font-weight:600;cursor:pointer}.button.secondary{background:var(--bg);color:var(--ink);border-color:var(--line)}
.stat-top{display:flex;justify-content:space-between;align-items:center}.stat-top .icon{color:var(--muted)}.stat-value{font-size:30px}.stat-change{color:var(--muted);font-size:11px;line-height:1.5}.stats{margin-bottom:22px}
.dashboard-grid{grid-template-columns:minmax(0,1.65fr) minmax(270px,1fr);margin-bottom:22px;align-items:stretch}.card-header h3{font-size:11px}.card-header{margin-bottom:18px}.section-subtitle{font-size:12px;color:var(--muted);margin:-7px 0 20px;line-height:1.6}
.inventory-summary{display:flex;align-items:baseline;gap:10px;margin:22px 0}.inventory-summary strong{font-size:32px;letter-spacing:-1px}.inventory-summary span{font-size:12px;color:var(--muted)}.stock-bar{height:12px;border-radius:6px;overflow:hidden;display:flex;background:var(--cream);border:1px solid var(--line)}.stock-bar span:first-child{width:88%;background:var(--ink)}.stock-bar span:nth-child(2){width:8%;background:var(--muted)}.legend{display:flex;justify-content:space-between;gap:14px;margin:18px 0 26px;font-size:11px;color:var(--muted);line-height:1.8}.legend b{display:block;color:var(--ink);font-size:16px}.mini-heading{font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:12px}.metric-row{display:flex;justify-content:space-between;padding:14px 0;border-top:1px solid var(--line);font-size:12px}.metric-row strong{font-weight:600}
.attention{background:var(--cream)}.alert-row{padding:15px 0;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:12px;font-size:12px;align-items:center}.alert-row strong{display:block;font-size:12px;margin-bottom:5px}.alert-row small{color:var(--muted);line-height:1.5}.pill{border:1px solid var(--line);background:var(--bg);padding:5px 8px;border-radius:20px;font-size:10px;white-space:nowrap}.wide-button{display:block;text-align:center;margin-top:16px}.shortcut-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.shortcut{display:flex;gap:12px;align-items:center;border:1px solid var(--line);border-radius:8px;padding:16px;color:var(--ink);text-decoration:none;font-size:12px;font-weight:600}.shortcut:hover{background:var(--cream)}.shortcut small{display:block;font-weight:400;color:var(--muted);font-size:11px;margin-top:5px}.shortcut .icon{width:20px;height:20px}.card table th{border-bottom-color:var(--line)}.card table td{font-size:12px}.numeric{text-align:right}.subcell{display:block;font-size:10px;color:var(--muted);margin-top:5px}.footer-note{font-size:11px;color:var(--muted);line-height:1.7;margin-top:18px}.notification::after{display:none}.notification{cursor:default}.preview-toast{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);background:var(--ink);color:var(--bg);padding:14px 20px;border-radius:8px;font-size:12px;z-index:30;max-width:90vw}.menu-item[hidden]{display:none}button:focus-visible,a:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
@media(max-width:1100px){.dashboard-grid{grid-template-columns:1fr}.shortcut-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.page-header h1{font-size:26px}.stats{grid-template-columns:1fr 1fr;gap:10px}.card{padding:18px}.stat-value{font-size:24px}.stat-title{font-size:9px}.shortcut-grid{grid-template-columns:1fr}.preview-note{font-size:10px}.legend{gap:8px}.actions{width:100%}}@media(max-width:380px){.stats{grid-template-columns:1fr}}
'''
shell = shell.replace('</head>', '<style>'+css+'</style></head>')
def icon(name):
    return f'<svg class="icon" aria-hidden="true"><use href="#i-{name}"/></svg>'
cards = ''.join(f'<article class="card"><div class="stat-top"><span class="stat-title">{title}</span>{icon(i)}</div><div class="stat-value">{value}</div><div class="stat-change">{detail}</div></article>' for title,value,detail,i in [
    ('Active products','248','Across 12 categories','box'),('Available stock','3,842','Sellable units in inventory','layers'),('Active branches','4','Stores, outlets & warehouses','building'),('Team members','18','6 currently online','users')])
alerts = ''.join(f'<div class="alert-row"><div><strong>{name}</strong><small>{detail}</small></div><span class="pill">{status}</span></div>' for name,detail,status in [('Basmati Rice · 5 kg','4 units left · minimum 10','Low stock'),('Sunflower Oil · 1 L','0 units left · minimum 15','Out of stock'),('Whole Wheat Flour · 5 kg','6 units left · minimum 10','Low stock')])
rows = ''.join(f'<tr><td><strong>{name}</strong><span class="subcell">{sku}</span></td><td><span class="status paid">{kind}</span></td><td class="numeric">{qty}</td><td class="numeric">{time}</td></tr>' for name,sku,kind,qty,time in [('Basmati Rice · 5 kg','SKU-RC-005','Stock in','+40','10:42 AM'),('Sunflower Oil · 1 L','SKU-OL-001','Stock out','−12','10:28 AM'),('Whole Wheat Flour · 5 kg','SKU-FL-005','Damaged','2','09:56 AM'),('Toor Dal · 1 kg','SKU-DL-001','Stock in','+60','09:35 AM')])
shortcuts = ''.join(f'<a class="shortcut" href="#">{icon(i)}<span>{name}<small>{detail}</small></span></a>' for name,detail,i in [('Products','Manage your catalog','box'),('Stock movements','Record inventory changes','layers'),('Employees','Manage your team','brief'),('Branches','Manage your locations','building')])
content = f'''
<div class="preview-note">DESIGN PROPOSAL 01 &nbsp;·&nbsp; Sample data for layout review &nbsp;·&nbsp; Existing dashboard unchanged</div>
<section class="content">
<div class="page-header"><div><div class="kicker">Business overview</div><h1>Your business, at a glance.</h1><p>Monitor inventory, review stock alerts, and keep your team moving.</p></div><div class="actions"><span class="date-box">26 OCT 2026</span><a class="button" href="#">{icon('box')} Manage products</a></div></div>
<div class="stats">{cards}</div>
<div class="dashboard-grid"><article class="card"><div class="card-header"><h3>Inventory overview</h3><a href="#">View inventory →</a></div><p class="section-subtitle">A clear view of product availability across your company.</p><div class="inventory-summary"><strong>218 / 248</strong><span>products above minimum stock</span></div><div class="stock-bar" role="img" aria-label="218 healthy products, 20 low stock products, 10 out of stock products"><span></span><span></span><span></span></div><div class="legend"><span><b>218</b>Healthy stock</span><span><b>20</b>Low stock</span><span><b>10</b>Out of stock</span></div><div class="metric-row"><span>Stock value at purchase price</span><strong>₹4,86,250.00</strong></div><div class="metric-row"><span>Damaged units</span><strong>12 units</strong></div></article>
<article class="card attention"><div class="card-header"><h3>Needs attention</h3><span class="pill">30 products</span></div><p class="section-subtitle">Prioritize these items for replenishment.</p>{alerts}<a class="button secondary wide-button" href="#">Review all stock alerts →</a></article></div>
<div class="dashboard-grid"><article class="card"><div class="card-header"><h3>Recent stock movements</h3><a href="#">View all →</a></div><div class="table-wrapper"><table><thead><tr><th>Product</th><th>Movement</th><th class="numeric">Units</th><th class="numeric">Today</th></tr></thead><tbody>{rows}</tbody></table></div></article>
<article class="card"><div class="card-header"><h3>Sales overview</h3><span class="pill">Planned module</span></div><div style="padding:22px 0 30px">{icon('bars')}<h2 style="font-size:19px;margin:18px 0 10px">Your sales story starts here.</h2><p class="section-subtitle" style="margin:0">Once sales recording is connected, this space will show revenue, orders, and your weekly trend.</p></div><div class="metric-row"><span>Revenue</span><strong>Not connected</strong></div><div class="metric-row"><span>Orders</span><strong>Not connected</strong></div></article></div>
<div class="mini-heading">Quick access</div><div class="shortcut-grid">{shortcuts}</div><p class="footer-note">Preview only. Figures are illustrative. Inventory is currently company-wide; branch-level stock is not represented in the existing inventory model.</p>
</section></main></div>
<div id="toast" class="preview-toast" role="status" hidden></div>
<script>
function toggleSidebar(){{document.getElementById('sidebar').classList.toggle('collapsed')}}
let timer;document.querySelectorAll('a').forEach(a=>a.addEventListener('click',e=>{{e.preventDefault();const t=document.getElementById('toast');t.textContent='Layout preview only — '+a.textContent.trim()+' will connect after approval.';t.hidden=false;clearTimeout(timer);timer=setTimeout(()=>t.hidden=true,3000)}}));
document.querySelector('.search-box input').addEventListener('input',e=>{{document.querySelectorAll('.menu-item').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(e.target.value.toLowerCase()))}});
</script></body></html>'''
(root / 'design-preview/dashboard-proposal.html').write_text(shell+content, encoding='utf-8')
print('Created design-preview/dashboard-proposal.html; production files untouched.')
